170:     private static bool IsWithinMount(string path, string mountPoint)
171:     {
172:         if (string.Equals(path, mountPoint, StringComparison.Ordinal))
173:             return true;
174:         if (string.Equals(mountPoint, "/", StringComparison.Ordinal))
175:             return path.StartsWith("/", StringComparison.Ordinal);
176: 
177:         var prefix = mountPoint.EndsWith("/", StringComparison.Ordinal)
178:             ? mountPoint
179:             : mountPoint + "/";
180:         return path.StartsWith(prefix, StringComparison.Ordinal);
181:     }
